-- SALY ONB v2: D-28/D-32; seis candidatas (3 NUEVA + 3 REVISION).
-- Sin DDL, grants, nodos, reasignaciones ni publicación. ONB-005 v1 queda intacta;
-- reconciliar antecedente compuesto antes de publicar 005A/B. Binding runtime pendiente.
BEGIN;
DO $check$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM saly.nucleo_nodos WHERE codigo='ONBOARDING' AND padre='EMPRESAS' AND nivel='MODULO') OR NOT EXISTS(SELECT 1 FROM saly.nucleo_familias WHERE codigo='ONBOARDING') THEN RAISE EXCEPTION 'ONB_V2_PRECONDITION'; END IF;
END $check$;
DO $onb$
DECLARE packs jsonb := $pack$[{"codigo":"SALY-ONB-005A","hechos":["onb_v2_escaneo_requerido","onb_v2_escaneo_realizado"],"paquete":{"tipo":"NUEVA","codigo":"SALY-ONB-005A","clave":"onb_escaneo_documento","familia":"ONBOARDING","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"ONBOARDING","modo":"SOLO_AQUI","dueno":"PRODUCTO","titulo":"Escaneo de documento independiente","descripcion":"Escanear documento de identidad cuando corresponda al flujo de extranjero o excepción; independiente del video corto. No guardar copias conforme ONB-008.","efecto":"BLOQUEAR","autoridad":"ONB-D28","impacto":"REVISAR","origen":{"tipo":"CHAT","ref":"D-28/2026-11-26/punto-1/SALY-ONB-005A; D-32/2026-11-26 alcance v2","solicitante":"DUENO via Claude"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"onb_v2_escaneo_requerido"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"onb_v2_escaneo_realizado"},"der":{"lit":false}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"onb_v2_escaneo_requerido":true,"onb_v2_escaneo_realizado":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"onb_v2_escaneo_requerido":true,"onb_v2_escaneo_realizado":true},"esperado":false}]},"fuente":"CERRADA; 03_Reglas_CERRADAS.md; D-28 punto 1; 08_Reglas_Almacenamiento_e_Intentos.md; D-32 autoriza paquete","dependencia":"ONB-032 ABIERTA: mecanismo de evidencia sin copia; ONB-005 original no se modifica.","casos_documentales":"Escaneo requerido realizado vs omitido."},{"codigo":"SALY-ONB-005B","hechos":["onb_v2_video_requerido","onb_v2_video_capturado"],"paquete":{"tipo":"NUEVA","codigo":"SALY-ONB-005B","clave":"onb_captura_video_corto","familia":"ONBOARDING","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"ONBOARDING","modo":"SOLO_AQUI","dueno":"PRODUCTO","titulo":"Captura independiente de video corto","descripcion":"Capturar video corto cuando corresponda al flujo de extranjero o excepción, como obligación independiente del escaneo de documento. Duración y mecanismo no decididos.","efecto":"