r":{"op":"=","izq":{"hecho":"onb_v2_evidencia_escaneo_disponible"},"der":{"lit":false}}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"onb_v2_evidencia_video_disponible"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"onb_v2_plantilla_origen_disponible"},"der":{"lit":false}}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"onb_v2_entrega_rrhh_requerida":true,"onb_v2_datos_cargados_disponibles":true,"onb_v2_evidencia_escaneo_disponible":true,"onb_v2_evidencia_video_disponible":true,"onb_v2_plantilla_origen_disponible":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"onb_v2_entrega_rrhh_requerida":true,"onb_v2_datos_cargados_disponibles":true,"onb_v2_evidencia_escaneo_disponible":true,"onb_v2_evidencia_video_disponible":true,"onb_v2_plantilla_origen_disponible":true},"esperado":false}],"version_anterior":1,"hash_anterior":"9272a8408b3dd6599b6ed04a385af3b5591bf1748c1826de21dc08fbdcc34eb8","motivo_revision":"D-28 precisa la decisión documental; D-32 autoriza revisión candidata sin publicar."},"fuente":"CERRADA; 03_Reglas_CERRADAS.md; D-28 punto 2; 08_Reglas_Almacenamiento_e_Intentos.md; D-32 autoriza paquete","dependencia":"ONB-032 ABIERTA; clave histórica inmutable en REVISION, no propiedad de bandeja.","casos_documentales":"Los cuatro elementos mínimos disponibles vs falta plantilla de origen."},{"codigo":"SALY-ONB-018","hechos":["onb_v2_revalidacion_requerida","onb_v2_ruta_extranjero_excepcion","onb_v2_identidad_previa_disponible","onb_v2_reval_base_propia","onb_v2_reval_reniec","onb_v2_reval_documento"],"paquete":{"tipo":"REVISION","codigo":"SALY-ONB-018","clave":"onb_revalidacion_propia","familia":"ONBOARDING","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"ONBOARDING","modo":"SOLO_AQUI","dueno":"PRODUCTO","titulo":"Fuentes de revalidación de identidad","descripcion":"Revalidar contra base propia si existe información; si no, contra RENIEC; para extranjeros y excepciones, contra el escaneo del documento. Precedencia extranjero/excepción con identidad propia previa permanece abierta; no se decide por esta condición.","efecto":"BLOQUEAR","autoridad":"ONB-D28","impacto":"REVISAR","origen":{"tipo":"CHAT","ref":"D-28/2026-11-26/punto-3/SALY-ONB-018; D-32/2026-11-26 alcance v2","solicitante":"DUENO via Claude"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"onb_v2_revalidacion_requerida"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"onb_v2_ruta_extranjero_excepcion"},"der":{"lit":false}},"der":{"op":"o","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"onb_v2_identidad_previa_disponible"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"onb_v2_reval_base_propia"},"der":{"lit":false}}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"onb_v2_identidad_previa_disponible"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"onb_v2_reval_reniec"},"der":{"lit":false}}}}},"der":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"onb_v2_ruta_extranjero_excepcion"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"onb_v2_identidad_previa_disponible"},"der":{"lit":false}}},"der":{"op":"=","izq":{"hecho":"onb_v2_reval_documento"},"der":{"lit":false}}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"onb_v2_revalidacion_requerida":true,"onb_v2_ruta_extranjero_excepcion":false,"onb_v2_identidad_previa_disponible":true,"onb_v2_reval_base_propia":false,"onb_v2_reval_reniec":true,"onb_v2_reval_documento":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"onb_v2_revalidacion_requerida":true,"onb_v2_ruta_extranjero_excepcion":false,"onb_v2_identidad_previa_disponible":true,"onb_v2_reval_base_propia":true,"onb_v2_reval_reniec":false,"onb_v2_reval_documento":false},"esperado":false}],"version_anterior":1,"hash_anterior":"f611716236924991a10c814955affe6f38f2d188b4d5719f0cc4edf5dab15cfd","motivo_revision":"D-28 precisa la decisión documental; D-32 autoriza revisión candidata sin publicar."},"fuente":"CERRADA; 03_Reglas_CERRADAS.md; D-28 punto 3; 08_Reglas_Almacenamiento_e_Intentos.md; D-32 autoriza paquete","dependencia":"ONB-031 ABIERTA; precedencia extranjero/excepción con identidad previa ABIERTA; condición no decide ese caso, no equivale a permitirlo.","casos_documentales":"Nacional revalida base propia disponible vs omite base propia usando RENIEC."},{"codigo":"SALY-ONB-019","hechos":["onb_v2_finalizacion_solicitada","onb_v2_biometria_realizada","onb_v2_capitulo_biometrico_incluido","onb_v2_biometria_capturada","onb_v2_consentimiento_biometrico_aceptado"],"paquete":{"tipo":"REVISION","codigo":"SALY-ONB-019","clave":"onb_capitulo_biometrico","familia":"ONBOARDING","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"ONBOARDING","modo":"SOLO_AQUI","dueno":"PRODUCTO","titulo":"Biometría y capítulo obligatorio","descripcion":"La biometría es obligatoria para onboarding, así como el capítulo biométrico de Protección de Datos. Si no acepta consentimiento, no continúa, no se da de baja y puede reintentar según ONB-021; texto legal pendiente bloquea producción según ONB-020.","efecto":"BLOQUEAR","autoridad":"ONB-D28","impacto":"REVISAR","origen":{"tipo":"CHAT","ref":"D-28/2026-11-26/punto-4/SALY-ONB-019; D-32/2026-11-26 alcance v2","solicitante":"DUENO via Claude"},"condicion":{"op":"o","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"onb_v2_finalizacion_solicitada"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"onb_v2_biometria_realizada"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"onb_v2_capitulo_biometrico_incluido"},"der":{"lit":false}}}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"onb_v2_biometria_capturada"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"onb_v2_consentimiento_biometrico_aceptado"},"der":{"lit":false}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"onb_v2_finalizacion_solicitada":true,"onb_v2_biometria_realizada":false,"onb_v2_capitulo_biometrico_incluido":true,"onb_v2_biometria_capturada":false,"onb_v2_consentimiento_biometrico_aceptado":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"onb_v2_finalizacion_solicitada":true,"onb_v2_biometria_realizada":true,"onb_v2_capitulo_biometrico_incluido":true,"onb_v2_biometria_capturada":true,"onb_v2_consentimiento_biometrico_aceptado":true},"esperado":false}],"version_anterior":1,"hash_anterior":"6fb59ee4ef8cb8af11e8def8ea75e001404f6856d7d0e08ca4eab62889640f16","motivo_revision":"D-28 precisa la decisión documental; D-32 autoriza revisión candidata sin publicar."},"fuente":"CERRADA; 03_Reglas_CERRADAS.md; D-28 punto 4; 08_Reglas_Almacenamiento_e_Intentos.md; D-32 autoriza paquete","dependencia":"ONB-029 ABIERTA; texto legal no homologado. No cambia ONB-020/021.","casos_documentales":"Finalización con biometría y capítulo, consentimiento aceptado vs finalización sin biometría."},{"codigo":"SALY-ONB-034","hechos":["onb_v2_biometria_capturada","onb_v2_biometria_en_base_propia","onb_v2_otra_base_identidad"],"paquete":{"tipo":"NUEVA","codigo":"SALY-ONB-034","clave":"onb_almacenamiento_biometria_propia","familia":"ONBOARDING","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"ONBOARDING","modo":"SOLO_AQUI","dueno":"PRODUCTO","titulo":"Almacenamiento biométrico en base propia única","descripcion":"Guardar información biométrica capturada en la misma base propia de identidad de ONB-023 sin crear otra base de identidad. Solo registro exitoso constituye identidad exitosa; biometría incompleta retención 30 días y exitosa según ONB-025/026. No definir segregación física ni cómputo.","efecto":"BLOQUEAR","autoridad":"ONB-D28","impacto":"REVISAR","origen":{"tipo":"CHAT","ref":"D-28/2026-11-26/punto-4/SALY-ONB-034; D-32/2026-11-26 alcance v2","solicitante":"DUENO via Claude"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"onb_v2_biometria_capturada"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"onb_v2_biometria_en_base_propia"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"onb_v2_otra_base_identidad"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"onb_v2_biometria_capturada":true,"onb_v2_biometria_en_base_propia":false,"onb_v2_otra_base_identidad":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"onb_v2_biometria_capturada":true,"onb_v2_biometria_en_base_propia":true,"onb_v2_otra_base_identidad":false},"esperado":false}]},"fuente":"CERRADA; 03_Reglas_CERRADAS.md; D-28 punto 4; 08_Reglas_Almacenamiento_e_Intentos.md; D-32 autoriza paquete","dependencia":"ONB-033 y 056 ABIERTAS: inicio, vencimiento y segregación provisional/exitosa; no se crean estructuras.","casos_documentales":"Biometría capturada guardada en base única vs guardada fuera/otra base."}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; ver int; t record; n int:=0; vectors int:=0;
BEGIN
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
  a:=p->'paquete'; cd:=p->>'codigo'; ver:=CASE WHEN a->>'tipo'='REVISION' THEN 2 ELSE 1 END;
  ans:=saly.nucleo_regla_proponer_v1(a,true);
  IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM ver THEN RAISE EXCEPTION 'ONB_V2_PROPOSAL_FAIL % %',cd,ans; END IF;
  IF NOT EXISTS(SELECT 1 FROM saly.nucleo_regla_versiones WHERE regla=cd AND version=ver AND estado='CANDIDATA') THEN RAISE EXCEPTION 'ONB_V2_STATE_FAIL %',cd; END IF;
  IF ver=2 AND NOT EXISTS(SELECT 1 FROM saly.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='DESCARTADA' AND hash=a->>'hash_anterior') THEN RAISE EXCEPTION 'ONB_V2_PRIOR_FAIL %',cd; END IF;
  FOR t IN SELECT entrada,esperado FROM saly.nucleo_regla_pruebas WHERE regla=cd AND version=ver LOOP
   IF saly.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'ONB_V2_VECTOR_FAIL %',cd; END IF;
   vectors:=vectors+1;
  END LOOP;
  IF NOT EXISTS(SELECT 1 FROM saly.nucleo_aplicaciones WHERE regla=cd AND nodo='ONBOARDING' AND modo='SOLO_AQUI') THEN RAISE EXCEPTION 'ONB_V2_APPLICATION_FAIL %',cd; END IF;
  n:=n+1;
 END LOOP;
 IF n<>6 OR vectors<>12 THEN RAISE EXCEPTION 'ONB_V2_COUNT_FAIL'; END IF;
 RAISE NOTICE 'ONB_V2_CANDIDATAS % VECTORES %',n,vectors;
END $onb$;
COMMIT;
